#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxPoints(vector<int>& primary, vector<int>& secondary, int k, int limit) {
        int n = primary.size();
        vector<pair<int, int>> tasks(n);
        for (int i = 0; i < n; i++) {
            tasks[i] = {primary[i], max(0, secondary[i] - primary[i])};
        }
        sort(tasks.begin(), tasks.end(), [](const auto& a, const auto& b) {
            return (a.first + a.second) > (b.first + b.second);
        });
        int baseSum = 0;
        vector<int> bonuses;
        for (int i = 0; i < k; i++) {
            baseSum += tasks[i].first;
            bonuses.push_back(tasks[i].second);
        }
        sort(bonuses.rbegin(), bonuses.rend());
        int ans = baseSum;
        int take = min((int)bonuses.size(), limit);
        for (int i = 0; i < take; i++) ans += bonuses[i];
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxPoints(int[] primary, int[] secondary, int k, int limit) {
        int n = primary.length;
        int[][] tasks = new int[n][2];
        for (int i = 0; i < n; i++) {
            tasks[i][0] = primary[i];
            tasks[i][1] = Math.max(0, secondary[i] - primary[i]);
        }
        Arrays.sort(tasks, (a, b) -> Integer.compare(b[0] + b[1], a[0] + a[1]));
        int baseSum = 0;
        List<Integer> bonuses = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            baseSum += tasks[i][0];
            bonuses.add(tasks[i][1]);
        }
        bonuses.sort(Collections.reverseOrder());
        int ans = baseSum;
        int take = Math.min(bonuses.size(), limit);
        for (int i = 0; i < take; i++) ans += bonuses.get(i);
        return ans;
    }
}

var maxPoints = function(primary, secondary, k, limit) {
    const tasks = primary.map((p, i) => [p, Math.max(0, secondary[i] - p)]);
    tasks.sort((a, b) => (b[0] + b[1]) - (a[0] + a[1]));
    const selected = tasks.slice(0, k);
    const baseSum = selected.reduce((sum, t) => sum + t[0], 0);
    const bonuses = selected.map(t => t[1]).sort((a, b) => b - a);
    const bonusSum = bonuses.slice(0, limit).reduce((sum, b) => sum + b, 0);
    return baseSum + bonusSum;
};
